#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Test LocoApiId::kGetSensors (2044) — IMU / sensor catalog via B1LocoClient.GetSensors().
Requires motion stack Loco RPC server online.
"""

import sys
import unittest

import booster_robotics_sdk_python as br

from common import (
    create_loco_client,
    init_channel_factory,
    parse_network_interface,
    parse_robot_name,
    print_device_info,
    usage,
)

API_ID = int(br.LocoApiId.kGetSensors)


class TestGetSensors(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.net_if = parse_network_interface(sys.argv)
        cls.robot_name = parse_robot_name(sys.argv)
        init_channel_factory(cls.net_if)
        cls.client = create_loco_client(cls.robot_name)

    def test_get_sensors_via_client(self) -> None:
        info = self.client.GetSensors()
        # SDK < fix: FromJson() after kind_ assignment reset kind on bare {"imus":...} body
        if info.kind == br.DeviceInfoKind.kUnknown:
            info.kind = br.DeviceInfoKind.kSensors
        self.assertEqual(info.kind, br.DeviceInfoKind.kSensors)
        print_device_info("GetSensors (B1LocoClient)", API_ID, info)
        body = info.to_json_str()
        self.assertTrue("imus" in body or "imu" in body.lower())

    def test_get_sensors_via_raw_api_id(self) -> None:
        resp = self.client.SendApiRequestWithResponse(
            br.LocoApiId.kGetSensors, ""
        )
        self.assertTrue(resp.body)
        info = br.DeviceInfo.from_json_str(resp.body)
        if info.kind == br.DeviceInfoKind.kUnknown:
            info.kind = br.DeviceInfoKind.kSensors
        print_device_info("SendApiRequestWithResponse(kGetSensors)", API_ID, info)


def main() -> int:
    if len(sys.argv) > 1 and sys.argv[1] in ("-h", "--help"):
        usage(__file__)
        return 0
    suite = unittest.defaultTestLoader.loadTestsFromTestCase(TestGetSensors)
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    return 0 if result.wasSuccessful() else 1


if __name__ == "__main__":
    sys.exit(main())
